@* Clock.razor *@
@implements IDisposable
@inject IJSRuntime JS

<p>Time: @time</p>

@code {
    private DotNetObjectReference<Clock>? objRef;
    private string time = "";

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            objRef = DotNetObjectReference.Create(this);
            await JS.InvokeVoidAsync("ticker.start", objRef);
        }
    }

    [JSInvokable]
    public void Tick(string now)
    {
        time = now;
        StateHasChanged();
    }

    public void Dispose() => objRef?.Dispose();
}
